845	    if (stmt.kind === 'tryCall') exprs.push(stmt.expr);
846	
847	    // External interactions textually present in this step.
848	    let hasInteraction = false;
849	    for (const expr of exprs) {
850	      walkExpr(expr, (n) => {
851	        if (isExternalInteraction(view, n)) hasInteraction = true;
852	      });
853	    }
854	
855	    // Any storage store in this statement executes only after every
856	    // expression (including external calls) has been evaluated, so a write
857	    // in a statement containing an interaction is always post-call.
858	    if ((interactionBefore || hasInteraction) && !fired) {
859	      walkStatement(stmt, (st) => {
860	        if (fired) return;
861	        let writes = [];
862	        if (st.kind === 'expression' && st.expr) {
863	          const e = st.expr;
864	          if (e.kind === 'assign') writes = [[e.target.loc, e.target]];
865	          else if (e.kind === 'unary' && (e.op === '++' || e.op === '--' || e.op === 'delete')) {
866	            writes = [[e.operand.loc, e.operand]];
867	          }
868	        }
869	        for (const [loc, target] of writes) {
870	          const sv = stateWriteRoot(view, target);
871	          if (sv) {
872	            fired = true;
873	            findings.push({
874	              ruleId: 'STATE_UPDATE_AFTER_CALL',
875	              origin: origin || desc,
876	              location: loc,
877	              stateVar: sv.name,
878	            });
879	            break;
880	          }
881	        }
882	      });
883	    }
884	
885	    if (hasInteraction) interactionBefore = true;
886	  }
887	  return findings;
888	}
889	
890	// ---- driver ----------------------------------------------------------------
891	
892	export function analyze(parsedFiles) {
893	  const registry = new Registry(parsedFiles);
894	  const views = registry.buildViews();
895	  const acc = new Map();
896	
897	  for (const view of views) {
898	    const reach = computeReachability(view);
899	    for (const desc of view.methods.values()) {
900	      if (!desc.node || !desc.node.body) continue;
901	      const wrapped = view.effectiveStatements(desc);
902	      const isEntry = view.entries.some((e) => e.node && descKey(e) === descKey(desc));
903	
904	      const raw = [
905	        ...runDelegatecallRule(view, desc, wrapped),
906	        ...runUncheckedCallRule(view, desc, wrapped),
907	        ...runStateUpdateRule(view, desc, wrapped, isEntry),
908	      ];
909	      const reachMap = reach.get(descKey(desc)) || new Map();
910	
911	      for (const r of raw) {
912	        const key = `${r.ruleId}:${r.origin.file}:${r.location.startOffset}:${r.location.endOffset}`;
913	        let f = acc.get(key);
914	        if (!f) {
915	          f = { ruleId: r.ruleId, severity: RULES[r.ruleId].severity,
916	            file: r.origin.file, location: r.location, detail: r, entries: new Map() };
917	          acc.set(key, f);
918	        }
919	        // Modifier-originated findings inherit the reachability of the
920	        // enclosing method (modifier code is inlined into it).
921	        const effectiveReach = (r.origin.kind === 'modifier') ? reachMap :
922	          (reach.get(descKey(r.origin)) || reachMap);
923	        for (const [ek, chain] of effectiveReach.entries()) {
924	          const prior = f.entries.get(ek);
925	          if (!prior || prior.chain.length > chain.length) f.entries.set(ek, { chain });
926	        }
927	      }
928	    }
929	  }
930	
931	  return finalize(acc);
932	}
933	
934	function finalize(acc) {
935	  const findings = [];
936	  for (const f of acc.values()) {
937	    const chains = [...f.entries.values()].map((v) => v.chain)
938	      .sort((a, b) => a.length - b.length);
939	    const entryPoints = [];
940	    const callChains = [];
941	    for (const chain of chains) {
942	      const entry = chain[0];
943	      if (!entryPoints.some((e) => e.name === entry.name && e.contract === entry.contract &&
944	                                  e.kind === entry.kind)) {
945	        entryPoints.push(entry);
946	        callChains.push(chain);
947	      }
948	    }
949	    const reachable = entryPoints.length > 0;
950	    const d = f.detail;
951	    let message;
952	    if (d.ruleId === 'DELEGATECALL_UNTRUSTED_TARGET') {
953	      message = 'delegatecall 的目标受函数参数、calldata、msg.sender、tx.origin 或可控存储值影响，可能执行攻击者指定的合约代码';
954	    } else if (d.ruleId === 'UNCHECKED_EXTERNAL_CALL') {
955	      message = `底层调用 ${d.prop} 的返回结果未在同函数后续控制流中检查，失败会被静默忽略`;
956	    } else {
957	      message = `公开入口在外部调用或转账之后写入重入敏感状态 ${d.stateVar}，违反 checks-effects-interactions 顺序`;
958	    }
959	    findings.push({
960	      ruleId: f.ruleId,
961	      severity: f.severity,
962	      message,
963	      location: {
964	        file: f.file,
965	        startLine: f.location.startLine,
966	        startColumn: f.location.startColumn,
967	        endLine: f.location.endLine,
968	        endColumn: f.location.endColumn,
969	      },
970	      reachable,
971	      evidence: {
972	        entryPoints: reachable ? entryPoints : [],
973	        callChain: reachable ? callChains[0] : [],
974	      },
975	    });
976	  }
977	  return findings;
978	}
