// ---- rule 3: state update after external interaction -----------------------
//
// Path-sensitive, cross-function. Every function / free function / modifier
// is analyzed as a "container": its modifier chain is inlined (modifier code
// shares the container's frame depth) and, for constructors, linearized base
// constructors are prepended as a call prefix.
//
// A may-CFG walk decides ordering:
//   * a write is witnessed by every external interaction (low-level calls,
//     transfers, contract-typed member calls, `new X(...)`) that occurs on
//     the SAME path before it;
//   * if/else branches never merge before a write — a then-branch
//     interaction cannot witness an else-branch write; events do flow to
//     statements following the construct (may-analysis);
//   * loops reach a fixed point: an interaction in an earlier iteration
//     witnesses a write in a later one;
//   * try/catch: the tried call precedes both success and catch clauses,
//     while clauses stay mutually exclusive;
//   * return / throw / revert terminate their path.
// Witnesses carry a function-frame depth: text in the container (or its
// inlined modifiers) = 1, a callee one internal call away = 2, ...
//
// Two artifacts are built:
//   * interactionIndex: for each callee, the interaction points reachable
//     inside it (existence only, with relative depths) — the summary used
//     when a call appears before a write in the caller;
//   * per-container writes: each state-write position plus every witness
//     visible before it. Reachability, entry points and shortest chains
//     then come from the existing BFS map in the driver.

function stateWriteRoot(view, expr) {
  let e = expr;
  while (e) {
    if (e.kind === 'ident') return view.stateVars.get(e.name) || null;
    if (e.kind === 'member' || e.kind === 'index') { e = e.object; continue; }
    return null;
  }
  return null;
}

function superTargets(view, callerDesc, name, argc) {
  const out = [];
  let started = false;
  for (const { file, contract } of view.linearized) {
    if (!started) { if (contract.name === callerDesc.contract) started = true; continue; }
    const t = findMethodInContract(view, contract, file, name, argc);
    if (t) out.push(t);
  }
  return out;
}

// Classify a member call, mirroring the old isExternalInteraction predicate,
// and resolve the internal dispatch targets when it is not external.
function classifyMemberCall(view, callerDesc, n) {
  const callee = n.callee;
  const argc = (n.args || []).length;
  if (ALL_LOW_LEVEL.has(callee.property)) return { external: true };
  if (callee.property === 'push' || callee.property === 'pop') {
    return { external: false, targets: [] };
  }
  const obj = callee.object;
  if (obj.kind === 'ident') {
    if (obj.name === 'this') return { external: true };
    if (obj.name === 'super') {
      return { external: false, targets: superTargets(view, callerDesc, callee.property, argc) };
    }
    const sv = view.stateVars.get(obj.name);
    if (sv) {
      const t = sv.node.typeNode;
      const isContract = t && t.kind === 'typeElementary' &&
        view.registry.contractByName.has(t.path[0]);
      return { external: isContract, targets: [] };
    }
    if (view.registry.contractByName.has(obj.name)) {
      const target = view.resolveMethod(callee.property, argc);
      if (target && target.kind === 'function' && target.node && target.node.body) {
        return { external: false, targets: [target] };
      }
    }
  }
  return { external: true };
}

function buildInteractionIndex(view) {
  // descKey -> [{origin, loc, depth}], depth relative to the queried
  // function (its own body and inlined modifiers = 1).
  const memo = new Map();

  const get = (d) => {
    const k = descKey(d);
    if (memo.has(k)) return memo.get(k);
    memo.set(k, []); // recursion guard
    if (!d.node || !d.node.body) return [];

    const out = [];
    const discharge = (n, origin, fd) => {
      const callee = n.callee;
      if (callee.kind === 'newExpr') {
        out.push({ origin, loc: n.loc, depth: fd });
        return;
      }
      if (callee.kind === 'ident') {
        if (BUILTIN_CALLS.has(callee.name)) return;
        const t = view.resolveMethod(callee.name, (n.args || []).length);
        if (t) {
          for (const w of get(t)) {
            out.push({ origin: w.origin, loc: w.loc, depth: fd + w.depth });
          }
        }
        return;
      }
      if (callee.kind === 'member') {
        const cls = classifyMemberCall(view, origin, n);
        if (cls.external) {
          out.push({ origin, loc: operationSpan(n), depth: fd });
        } else {
          for (const t of cls.targets) {
            for (const w of get(t)) {
              out.push({ origin: w.origin, loc: w.loc, depth: fd + w.depth });
            }
          }
        }
      }
    };

    eachStatement(view.effectiveStatements(d), (stmt, origin) => {
      const exprs = statementExpressions(stmt);
      if (stmt.kind === 'try' && stmt.externalCall) exprs.push(stmt.externalCall);
      for (const expr of exprs) {
        walkExpr(expr, (n) => {
          if (n.kind === 'call') discharge(n, origin || d, 1);
        });
      }
    });

    const best = new Map();
    for (const w of out) {
      const wk = `${descKey(w.origin)}:${w.origin.file}:${w.loc.startOffset}`;
      const prior = best.get(wk);
      if (!prior || prior.depth > w.depth) best.set(wk, w);
    }
    const res = [...best.values()];
    memo.set(k, res);
    return res;
  };

  return { get };
}

function analyzeContainer(view, index, desc) {
  if (!desc.node || !desc.node.body) return [];
  // write position -> {file, location, stateVar, ws: witnesses}
  const writes = new Map();

  const wkey = (w) =>
    `${descKey(w.origin)}:${w.origin.file}:${w.loc.startOffset}:${w.depth}`;
  const merge = (...lists) => {
    const seen = new Set();
    const out = [];
    for (const list of lists) {
      for (const w of list) {
        const k = wkey(w);
        if (!seen.has(k)) { seen.add(k); out.push(w); }
      }
    }
    return out;
  };

  // External interactions textually in an expression at container frame
  // depth 1, plus summaries of internal calls (callee frame = depth+1).
  const atomsOf = (expr, origin) => {
    const out = [];
    if (!expr) return out;
    walkExpr(expr, (n) => {
      if (n.kind !== 'call') return;
      const callee = n.callee;
      if (callee.kind === 'newExpr') {
        out.push({ origin, loc: n.loc, depth: 1 });
        return;
      }
      if (callee.kind === 'ident') {
        if (BUILTIN_CALLS.has(callee.name)) return;
        const t = view.resolveMethod(callee.name, (n.args || []).length);
        if (t) {
          for (const w of index.get(t)) {
            out.push({ origin: w.origin, loc: w.loc, depth: 1 + w.depth });
          }
        }
        return;
      }
      if (callee.kind === 'member') {
        const cls = classifyMemberCall(view, origin, n);
        if (cls.external) {
          out.push({ origin, loc: operationSpan(n), depth: 1 });
        } else {
          for (const t of cls.targets) {
            for (const w of index.get(t)) {
              out.push({ origin: w.origin, loc: w.loc, depth: 1 + w.depth });
            }
          }
        }
      }
    });
    return out;
  };

  const recordWrite = (loc, target, origin, ws) => {
    const sv = stateWriteRoot(view, target);
    if (!sv) return;
    const key = `${origin.file}:${loc.startOffset}:${loc.endOffset}`;
    let entry = writes.get(key);
    if (!entry) {
      entry = { file: origin.file, location: loc, stateVar: sv.name, ws: [] };
      writes.set(key, entry);
    }
    for (const w of ws) {
      if (!entry.ws.some((x) => wkey(x) === wkey(w))) entry.ws.push(w);
    }
  };

  // Extract storage writes of a simple statement.
  const writesOf = (stmt) => {
    if (stmt.kind !== 'expression' || !stmt.expr) return [];
    const e = stmt.expr;
    if (e.kind === 'assign') return [[e.target.loc, e.target]];
    if (e.kind === 'unary' && (e.op === '++' || e.op === '--' || e.op === 'delete')) {
      return [[e.operand.loc, e.operand]];
    }
    return [];
  };

