  // reaching the point right after this region (null = unreachable because
  // every path terminates).
  const recList = (items, pre) => {
    let carry = pre;
    for (const { stmt, origin } of items) {
      const r = rec(stmt, origin, carry);
      if (r.term) return { after: null, term: true };
