  };

  const rec = (s, origin, pre) => {
    const asItems = (block) =>
      (block.statements || []).map((stmt) => ({ stmt, origin }));

    switch (s.kind) {
      case 'block': return recList(asItems(s), pre);
      case 'unchecked': return rec(s.body, origin, pre);

      case 'if': {
