        const rt = rec(s.consequent, origin, preC);
        if (!s.alternate) {
          // Two falling paths: condition false, or a non-terminating then.
          const parts = [preC];
          if (!rt.term) parts.push(rt.after);
          return { after: merge(...parts), term: false };
        }
        const re = rec(s.alternate, origin, preC);
        const parts = [];
        if (!rt.term) parts.push(rt.after);
        if (!re.term) parts.push(re.after);
        return { after: parts.length ? merge(...parts) : null, term: rt.term && re.term };
      }

      case 'while': {
        const preC = merge(pre, atomsOf(s.test, origin));
        let carry = preC;
        for (let guard = 0; guard < 20; guard++) {
          const rb = rec(s.body, origin, carry);
          const next = rb.term ? carry : merge(carry, rb.after);
          if (next.length === carry.length) break;
          carry = next;
        }
        // Exit via a false condition always exists (may-analysis).
        return { after: carry, term: false };
      }

      case 'doWhile': {
        let carry = pre;
        for (let guard = 0; guard < 20; guard++) {
          const rb = rec(s.body, origin, carry);
