        return { after: carry, term: false };
      }

      case 'try': {
        const preTry = merge(pre, atomsOf(s.externalCall, origin));
        const parts = [];
        const rb = rec(s.body, origin, preTry);
        if (!rb.term) parts.push(rb.after);
        for (const clause of s.clauses || []) {
          const rc = rec(clause, origin, preTry);
          if (!rc.term) parts.push(rc.after);
        }
        // No catch clause: a failed call reverts, only the success path
        // reaches the statements after the try.
        return { after: parts.length ? merge(...parts) : null, term: parts.length === 0 };
      }

      case 'return':
      case 'throw':
        return { after: null, term: true };

      case 'break':
      case 'continue':
        // Coarse may-analysis: another iteration can still supply the
        // events gathered so far.
        return { after: pre, term: false };

      case 'varDecl': {
        const atoms = s.initializer ? atomsOf(s.initializer, origin) : [];
        return { after: merge(pre, atoms), term: false };
      }

      case 'emit': {
        const atoms = s.expr ? atomsOf(s.expr, origin) : [];
        return { after: merge(pre, atoms), term: false };
      }

      case 'expression': {
        if (isRevertCall(s.expr)) return { after: null, term: true };
        const atoms = atomsOf(s.expr, origin);
        const ws = merge(pre, atoms);
        for (const [loc, target] of writesOf(s)) {
          recordWrite(loc, target, origin, ws);
        }
        return { after: ws, term: false };
      }

      default:
        return { after: pre, term: false };
    }
  };

  // Constructor prefix: linearized base constructors run before the body.
  let initial = [];
  if (desc.kind === 'constructor') {
    const bases = [];
    let passedSelf = false;
    for (const { file, contract } of view.linearized) {
      if (!passedSelf) { if (contract.name === desc.contract) passedSelf = true; continue; }
      const node = (contract.nodes || []).find((fn) => fn.functionKind === 'constructor');
      if (node) {
        bases.push({ ...descriptorFor(node, file, contract.name, (node.params || []).length), node });
      }
    }
    for (const b of bases) {
      for (const w of index.get(b)) {
        initial.push({ origin: w.origin, loc: w.loc, depth: 1 + w.depth });
      }
    }
  }

  rec(view.effectiveStatements(desc), initial);
  return [...writes.values()];
}

