function buildInteractionIndex(view) {
  // descKey -> [{origin, loc, depth}], depth relative to the queried
  // function (its own body and inlined modifiers = 1).
  const memo = new Map();

  const get = (d) => {
    const k = descKey(d);
    if (memo.has(k)) return memo.get(k);
    memo.set(k, []); // recursion guard
    if (!d.node || !d.node.body) return [];

    const out = [];
    const discharge = (n, origin, fd) => {
      const callee = n.callee;
      if (callee.kind === 'newExpr') {
        out.push({ origin, loc: n.loc, depth: fd });
        return;
      }
      if (callee.kind === 'ident') {
        if (BUILTIN_CALLS.has(callee.name)) return;
        const t = view.resolveMethod(callee.name, (n.args || []).length);
        if (t) {
          for (const w of get(t)) {
            out.push({ origin: w.origin, loc: w.loc, depth: fd + w.depth });
          }
        }
        return;
      }
      if (callee.kind === 'member') {
        const cls = classifyMemberCall(view, origin, n);
        if (cls.external) {
          out.push({ origin, loc: operationSpan(n), depth: fd });
        } else {
          for (const t of cls.targets) {
            for (const w of get(t)) {
              out.push({ origin: w.origin, loc: w.loc, depth: fd + w.depth });
            }
          }
        }
      }
    };

    eachStatement(view.effectiveStatements(d), (stmt, origin) => {
      const exprs = statementExpressions(stmt);
      if (stmt.kind === 'try') exprs.push(stmt.externalCall);
      for (const expr of exprs) {
        walkExpr(expr, (n) => {
          if (n.kind === 'call') discharge(n, origin || d, 1);
        });
      }
    });

    const best = new Map();
    for (const w of out) {
