function buildInteractionIndex(view) {
  // descKey -> [{file, loc, depth, anchorKey}], depth relative to the
  // queried function (its own body and inlined modifiers = 1). The anchor
  // is the non-modifier function whose reachability governs the point:
  // inlined modifier code shares the enclosing function's frame.
  const memo = new Map();

  const get = (d) => {
    const k = descKey(d);
    if (memo.has(k)) return memo.get(k);
    memo.set(k, []); // recursion guard
    if (!d.node || !d.node.body) return [];

    const out = [];
    const discharge = (n, origin, fd) => {
      const callee = n.callee;
      if (callee.kind === 'newExpr') {
        out.push({ file: origin.file, loc: n.loc, depth: fd, anchorKey: k });
        return;
      }
      if (callee.kind === 'ident') {
        if (BUILTIN_CALLS.has(callee.name)) return;
        const t = view.resolveMethod(callee.name, (n.args || []).length);
        if (t) {
          for (const w of get(t)) {
            out.push({ file: w.file, loc: w.loc, depth: fd + w.depth, anchorKey: w.anchorKey });
          }
        }
        return;
      }
      if (callee.kind === 'member') {
        const cls = classifyMemberCall(view, origin, n);
        if (cls.external) {
          out.push({ file: origin.file, loc: operationSpan(n), depth: fd, anchorKey: k });
        } else {
          for (const t of cls.targets) {
            for (const w of get(t)) {
              out.push({ file: w.file, loc: w.loc, depth: fd + w.depth, anchorKey: w.anchorKey });
            }
          }
        }
      }
    };

    eachStatement(view.effectiveStatements(d), (stmt, origin) => {
      const exprs = statementExpressions(stmt);
      if (stmt.kind === 'try' && stmt.externalCall) exprs.push(stmt.externalCall);
      for (const expr of exprs) {
        walkExpr(expr, (n) => {
          if (n.kind === 'call') discharge(n, origin || d, 1);
        });
      }
    });

    const best = new Map();
    for (const w of out) {
      const wk = `${w.anchorKey}:${w.file}:${w.loc.startOffset}`;
      const prior = best.get(wk);
      if (!prior || prior.depth > w.depth) best.set(wk, w);
    }
    const res = [...best.values()];
    memo.set(k, res);
    return res;
  };

  return { get };
}

