mkdir -p /tmp/cs1 && cat > /tmp/cs1/s.sol <<'EOF'
pragma solidity ^0.8.0;
contract Reentry {
    mapping(address => uint256) balances;
    uint256 total;
    function bad(address to, uint256 v) public {
        to.call{value: v}("");
        balances[msg.sender] = 0;
    }
    function good(address to, uint256 v) public {
        balances[msg.sender] = 0;
        to.call{value: v}("");
    }
    function transferThenWrite(address payable to) public {
        to.transfer(1);
        total += 1;
    }
    function internalOnly(address to) internal {
        to.call("");
        total = 1;
    }
}
EOF
node bin/contract-sentry.js audit /tmp/cs1/s.sol

