mkdir -p /tmp/cs2 && cat > /tmp/cs2/x.sol <<'EOF'
pragma solidity ^0.8.0;
contract X {
    uint256 a;
    uint256 b;
    // caller interacts, callee writes (forward relay)
    function e1(address to) public {
        to.call("");
        h1();
    }
    function h1() internal { a = 1; }

    // callee interacts, caller writes (backward relay)
    function e2(address to) public {
        h2(to);
        b = 2;
    }
    function h2(address to) internal { to.transfer(1); }

    // mutually exclusive branches: interaction in then, write in else => no
    function e3(address to, bool ok) public {
        if (ok) { to.call(""); } else { a = 1; }
    }
    // same branch => yes
    function e4(address to, bool ok) public {
        if (ok) { to.call(""); a = 1; }
    }
    // interaction in then, write AFTER if => yes (merge)
    function e5(address to, bool ok) public {
        if (ok) { to.call(""); }
        a = 1;
    }

    // loop: earlier iteration witnesses later write
    function e6(address to) public {
        for (uint i = 0; i < 3; i++) {
            if (i > 0) { a = 1; }
            to.call("");
        }
    }
}
