    if (stmt.kind !== 'expression' || !stmt.expr) return [];
    const e = stmt.expr;
    if (e.kind === 'assign') return [[e.target.loc, e.target]];
    if (e.kind === 'unary' && (e.op === '++' || e.op === '--' || e.op === 'delete')) {
      return [[e.operand.loc, e.operand]];
    }
    return [];
  };

  // Returns {after: witnesses|null, term}: `after` is the interaction set
  // reaching the point right after this region (null = unreachable because
  // every path terminates).
  const recList = (items, pre) => {
    let carry = pre;
    for (const { stmt, origin } of items) {
      const r = rec(stmt, origin, carry);
      if (r.term) return { after: null, term: true };
      carry = r.after;
    }
    return { after: carry, term: false };
  };

  const rec = (s, origin, pre) => {
    const asItems = (block) =>
      (block.statements || []).map((stmt) => ({ stmt, origin }));

    switch (s.kind) {
      case 'block': return recList(asItems(s), pre);
      case 'unchecked': return rec(s.body, origin, pre);

      case 'if': {
        const preC = merge(pre, atomsOf(s.test, origin));
        const rt = rec(s.consequent, origin, preC);
        if (!s.alternate) {
          // Two falling paths: condition false, or a non-terminating then.
          const parts = [preC];
          if (!rt.term) parts.push(rt.after);
          return { after: merge(...parts), term: false };
        }
        const re = rec(s.alternate, origin, preC);
        const parts = [];
        if (!rt.term) parts.push(rt.after);
        if (!re.term) parts.push(re.after);
        return { after: parts.length ? merge(...parts) : null, term: rt.term && re.term };
      }

      case 'while': {
        const preC = merge(pre, atomsOf(s.test, origin));
        let carry = preC;
        for (let guard = 0; guard < 20; guard++) {
          const rb = rec(s.body, origin, carry);
          const next = rb.term ? carry : merge(carry, rb.after);
          if (next.length === carry.length) break;
          carry = next;
        }
        // Exit via a false condition always exists (may-analysis).
        return { after: carry, term: false };
      }

      case 'doWhile': {
        let carry = pre;
        for (let guard = 0; guard < 20; guard++) {
          const rb = rec(s.body, origin, carry);
          let next = rb.term ? carry : merge(carry, rb.after);
          next = merge(next, atomsOf(s.test, origin));
          if (next.length === carry.length) break;
          carry = next;
        }
        return { after: carry, term: false };
      }

      case 'for': {
        let carry = pre;
        if (s.init) {
          const ri = rec(s.init, origin, carry);
          if (!ri.term) carry = ri.after;
        }
        for (let guard = 0; guard < 20; guard++) {
          if (s.test) carry = merge(carry, atomsOf(s.test, origin));
          const rb = rec(s.body, origin, carry);
          let next = rb.term ? carry : merge(carry, rb.after);
          if (s.update) next = merge(next, atomsOf(s.update, origin));
          if (next.length === carry.length) break;
          carry = next;
        }
        return { after: carry, term: false };
      }

      case 'try': {
        const preTry = merge(pre, atomsOf(s.externalCall, origin));
        const parts = [];
        const rb = rec(s.body, origin, preTry);
        if (!rb.term) parts.push(rb.after);
        for (const clause of s.clauses || []) {
          const rc = rec(clause, origin, preTry);
          if (!rc.term) parts.push(rc.after);
        }
        // No catch clause: a failed call reverts, only the success path
        // reaches the statements after the try.
        return { after: parts.length ? merge(...parts) : null, term: parts.length === 0 };
      }

      case 'return':
      case 'throw':
        return { after: null, term: true };

      case 'break':
      case 'continue':
        // Coarse may-analysis: another iteration can still supply the
        // events gathered so far.
        return { after: pre, term: false };

      case 'varDecl': {
        const atoms = s.initializer ? atomsOf(s.initializer, origin) : [];
        return { after: merge(pre, atoms), term: false };
      }

      case 'emit': {
        const atoms = s.expr ? atomsOf(s.expr, origin) : [];
        return { after: merge(pre, atoms), term: false };
      }

      case 'expression': {
        if (isRevertCall(s.expr)) return { after: null, term: true };
        const atoms = atomsOf(s.expr, origin);
        const ws = merge(pre, atoms);
        for (const [loc, target] of writesOf(s)) {
          recordWrite(loc, target, origin, ws);
        }
        return { after: ws, term: false };
      }

      default:
        return { after: pre, term: false };
    }
  };

  // Constructor prefix: linearized base constructors run before the body.
  let initial = [];
  if (desc.kind === 'constructor') {
    const bases = [];
    let passedSelf = false;
    for (const { file, contract } of view.linearized) {
      if (!passedSelf) { if (contract.name === desc.contract) passedSelf = true; continue; }
      const node = (contract.nodes || []).find((fn) => fn.functionKind === 'constructor');
      if (node) {
        bases.push({ ...descriptorFor(node, file, contract.name, (node.params || []).length), node });
      }
    }
    for (const b of bases) {
      for (const w of index.get(b)) {
        initial.push({ file: w.file, loc: w.loc, depth: 1 + w.depth, anchorKey: w.anchorKey });
      }
    }
  }

  recList(view.effectiveStatements(desc), initial);
  return [...writes.values()];
}

// ---- rule 3: state update after external interaction -----------------------
//
// Path-sensitive, cross-function. Every function / free function / modifier
// is analyzed as a "container": its modifier chain is inlined (modifier code
// shares the container's frame depth) and, for constructors, linearized base
// constructors are prepended as a call prefix.
//
// A may-CFG walk decides ordering:
//   * a write is witnessed by every external interaction (low-level calls,
//     transfers, contract-typed member calls, `new X(...)`) that occurs on
//     the SAME path before it;
//   * if/else branches never merge before a write — a then-branch
//     interaction cannot witness an else-branch write; events do flow to
//     statements following the construct (may-analysis);

