        evalExpr(expr.right, origin, frame, carry, out);
        break;
      case 'unary': evalExpr(expr.operand, origin, frame, carry, out); break;
      case 'assign':
        evalExpr(expr.target, origin, frame, carry, out);
        evalExpr(expr.value, origin, frame, carry, out);
        break;
      case 'conditional':
        evalExpr(expr.test, origin, frame, carry, out);
        evalExpr(expr.cons, origin, frame, carry, out);
        evalExpr(expr.alt, origin, frame, carry, out);
        break;
      case 'member': evalExpr(expr.object, origin, frame, carry, out); break;
      case 'index':
        evalExpr(expr.object, origin, frame, carry, out);
        if (expr.index) evalExpr(expr.index, origin, frame, carry, out);
        break;
      case 'tuple':
        for (const it of expr.items || []) evalExpr(it, origin, frame, carry, out);
        break;
      case 'structLiteral':
        for (const fld of expr.fields || []) evalExpr(fld.value, origin, frame, carry, out);
        break;
      case 'call': {
        // Evaluate target/arguments/options first.
        evalExpr(expr.callee, origin, frame, carry, out);
        for (const a of expr.args || []) evalExpr(a, origin, frame, carry, out);
        for (const o of expr.options || []) evalExpr(o.value, origin, frame, carry, out);

        const callee = expr.callee;
        if (callee.kind === 'newExpr') {
          out.push(makeAtom(origin.file, expr.loc, frame));
          break;
        }
        if (callee.kind === 'ident') {
          if (BUILTIN_CALLS.has(callee.name)) break;
          const t = view.resolveMethod(callee.name, (expr.args || []).length);
          invokeTargets(t ? [t] : [], frame, carry, out);
          break;
        }
        if (callee.kind === 'member') {
          const cls = classifyMemberCall(view, frame.desc, expr);
          if (cls.external) {
            out.push(makeAtom(origin.file, operationSpan(expr), frame));
          } else {
            invokeTargets(cls.targets, frame, carry, out);
          }
        }
        break;
      }
      default: break;
    }
  };

  const atomsOf = (expr, origin, frame, carry) => {
    const out = [];
    evalExpr(expr, origin, frame, carry, out);
    return out;
  };

  const recordWrite = (loc, target, origin, frame, ws) => {
    const sv = stateWriteRoot(view, target);
    if (!sv) return;
    const key = `${origin.file}:${loc.startOffset}:${loc.endOffset}`;
    let entry = writes.get(key);
    if (!entry) {
      entry = {
        file: origin.file, location: loc, stateVar: sv.name,
        frameKey: descKey(frame.desc), witnesses: new Map(),
      };
      writes.set(key, entry);
    }
    for (const w of ws) {
      // Frame distance between interaction and write on the shared path.
      const witnessed = {
        file: w.file, loc: w.loc,
        depth: Math.abs(w.di - frame.depth) + 1,
        frameKey: w.frameKey,
        rootKeys: new Set(w.rootKeys),
      };
      const k = witnessKeyOf(witnessed);
      const prior = entry.witnesses.get(k);
      if (!prior || prior.depth > witnessed.depth) {
        entry.witnesses.set(k, witnessed);
      } else {
        for (const rk of witnessed.rootKeys) prior.rootKeys.add(rk);
      }
    }
  };

  const writesOf = (stmt) => {
    if (stmt.kind !== 'expression' || !stmt.expr) return [];
    const e = stmt.expr;
    if (e.kind === 'assign') return [[e.target.loc, e.target]];
    if (e.kind === 'unary' && (e.op === '++' || e.op === '--' || e.op === 'delete')) {
      return [[e.operand.loc, e.operand]];
    }
    return [];
  };

  const api = { atomsOf, recordWrite, writesOf, walkStatements: null, constructorPrefix: null };

  // Constructor prefix: linearized base constructors run before the body,
  // each one internal call deeper. Returns interactions reaching the point
  // right before the body starts.
  function constructorPrefix(viewArg, frame, carry) {
    let acc = carry;
    let passedSelf = false;
    for (const { file, contract } of viewArg.linearized) {
      if (!passedSelf) { if (contract.name === frame.desc.contract) passedSelf = true; continue; }
      const node = (contract.nodes || []).find((fn) => fn.functionKind === 'constructor');
      if (!node || !node.body) continue;
      const b = { ...descriptorFor(node, file, contract.name, (node.params || []).length), node };
      const bk = descKey(b);
      if (frame.stack.has(bk) || frame.depth + 1 > MAX_INLINE_DEPTH) continue;
      const inner = { desc: b, depth: frame.depth + 1, stack: frame.stack, rootKey: frame.rootKey };
      frame.stack.add(bk);
      let prePrefix = [];
      const r = walkStatements(viewArg, b, inner, mergeW(acc, prePrefix), api);
      frame.stack.delete(bk);
      if (!r.term) acc = mergeW(acc, r.after);
    }
    return acc === carry ? [] : acc;
  }
  api.constructorPrefix = constructorPrefix;

  // Walk one frame's effective statements. Returns {after, term}.
  function walkStatements(viewArg, desc, frame, pre, apiArg) {
    const items = viewArg.effectiveStatements(desc);

    const recList = (list, carryIn) => {
      let carry = carryIn;
      for (const { stmt, origin } of list) {
        const r = rec(stmt, origin, carry);
        if (r.term) return { after: null, term: true };
        carry = r.after;
      }
      return { after: carry, term: false };
    };

    const rec = (s, origin, carryP) => {
      switch (s.kind) {
        case 'block':
          return recList((s.statements || []).map((stmt) => ({ stmt, origin })), carryP);
        case 'unchecked':
          return rec(s.body, origin, carryP);

        case 'if': {
          const preC = mergeW(carryP, apiArg.atomsOf(s.test, origin, frame, carryP));
          const rt = rec(s.consequent, origin, preC);
          if (!s.alternate) {
            const parts = [preC];
            if (!rt.term) parts.push(rt.after);
            return { after: mergeW(...parts), term: false };
          }
          const re = rec(s.alternate, origin, preC);
          const parts = [];
          if (!rt.term) parts.push(rt.after);
          if (!re.term) parts.push(re.after);
          return { after: parts.length ? mergeW(...parts) : null, term: rt.term && re.term };
        }

        case 'while': {
          const preC = mergeW(carryP, apiArg.atomsOf(s.test, origin, frame, carryP));
          let carry = preC;
          for (let guard = 0; guard < 20; guard++) {
            const rb = rec(s.body, origin, carry);
            const next = rb.term ? carry : mergeW(carry, rb.after);
            if (next.length === carry.length) break;
            carry = next;
          }
          return { after: carry, term: false };
        }

        case 'doWhile': {
          let carry = carryP;
          for (let guard = 0; guard < 20; guard++) {
            const rb = rec(s.body, origin, carry);
            let next = rb.term ? carry : mergeW(carry, rb.after);
            next = mergeW(next, apiArg.atomsOf(s.test, origin, frame, carry));
            if (next.length === carry.length) break;
            carry = next;
          }
          return { after: carry, term: false };
        }

        case 'for': {
          let carry = carryP;
          if (s.init) {
            const ri = rec(s.init, origin, carry);
            if (!ri.term) carry = ri.after;
          }
          for (let guard = 0; guard < 20; guard++) {
            if (s.test) carry = mergeW(carry, apiArg.atomsOf(s.test, origin, frame, carry));
            const rb = rec(s.body, origin, carry);
            let next = rb.term ? carry : mergeW(carry, rb.after);
            if (s.update) next = mergeW(next, apiArg.atomsOf(s.update, origin, frame, carry));
            if (next.length === carry.length) break;
            carry = next;
          }
          return { after: carry, term: false };
        }

        case 'try': {
          const preTry = mergeW(carryP, apiArg.atomsOf(s.externalCall, origin, frame, carryP));
          const parts = [];
          const rb = rec(s.body, origin, preTry);
          if (!rb.term) parts.push(rb.after);
          for (const clause of s.clauses || []) {
            const rc = rec(clause, origin, preTry);
            if (!rc.term) parts.push(rc.after);
          }
          return { after: parts.length ? mergeW(...parts) : null, term: parts.length === 0 };
        }

        case 'return':
        case 'throw':
          return { after: null, term: true };

        case 'break':
        case 'continue':
          return { after: carryP, term: false };

        case 'varDecl': {
          const atoms = s.initializer
            ? apiArg.atomsOf(s.initializer, origin, frame, carryP) : [];
          return { after: mergeW(carryP, atoms), term: false };
        }

        case 'emit': {
          const atoms = s.expr ? apiArg.atomsOf(s.expr, origin, frame, carryP) : [];
          return { after: mergeW(carryP, atoms), term: false };
        }

        case 'expression': {
          if (isRevertCall(s.expr)) return { after: null, term: true };
          const atoms = apiArg.atomsOf(s.expr, origin, frame, carryP);
          const ws = mergeW(carryP, atoms);
          for (const [loc, target] of apiArg.writesOf(s)) {
            apiArg.recordWrite(loc, target, origin, frame, ws);
          }
          return { after: ws, term: false };
        }

        default:
          return { after: carryP, term: false };
      }
    };

    return recList(items, pre);
  }
  api.walkStatements = walkStatements;

  // One root walk per method (entries and non-entries alike): a pattern
  // reachable only inside an unreachable helper is still reported, with
  // reachable=false.
  for (const root of view.methods.values()) {
    if (!root.node || !root.node.body) continue;
    const rk = descKey(root);
    const frame = { desc: root, depth: 1, stack: new Set([rk]), rootKey: rk };
    let initial = [];
    if (root.kind === 'constructor') initial = constructorPrefix(view, frame, []);
    walkStatements(view, root, frame, initial, api);
  }

  return writes;
}

