// ---- driver ----------------------------------------------------------------

export function analyze(parsedFiles) {
  const registry = new Registry(parsedFiles);
  const views = registry.buildViews();
  const acc = new Map();

  for (const view of views) {
    const reach = computeReachability(view);
    const index = buildInteractionIndex(view);
    for (const desc of view.methods.values()) {
      if (!desc.node || !desc.node.body) continue;
      const wrapped = view.effectiveStatements(desc);

      const otherRaw = [
        ...runDelegatecallRule(view, desc, wrapped),
        ...runUncheckedCallRule(view, desc, wrapped),
      ];
      const stateRaw = analyzeContainer(view, index, desc).flatMap((w) =>
        w.ws.length
          ? [{
              ruleId: 'STATE_UPDATE_AFTER_CALL',
              origin: w.origin,
              location: w.location,
              stateVar: w.stateVar,
              witnesses: w.ws,
            }]
          : []);
      const reachMap = reach.get(descKey(desc)) || new Map();

      for (const r of otherRaw) {
        const key = `${r.ruleId}:${r.origin.file}:${r.location.startOffset}:${r.location.endOffset}`;
        let f = acc.get(key);
        if (!f) {
          f = { ruleId: r.ruleId, severity: RULES[r.ruleId].severity,
            file: r.origin.file, location: r.location, detail: r, entries: new Map() };
          acc.set(key, f);
        }
        // Modifier-originated findings inherit the reachability of the
        // enclosing method (modifier code is inlined into it).
        const effectiveReach = (r.origin.kind === 'modifier') ? reachMap :
          (reach.get(descKey(r.origin)) || reachMap);
        for (const [ek, chain] of effectiveReach.entries()) {
          const prior = f.entries.get(ek);
          if (!prior || prior.chain.length > chain.length) f.entries.set(ek, { chain });
        }
      }

      for (const r of stateRaw) {
        const key = `${r.ruleId}:${r.origin.file}:${r.location.startOffset}:${r.location.endOffset}`;
        let f = acc.get(key);
        if (!f) {
          f = {
            ruleId: r.ruleId, severity: RULES[r.ruleId].severity,
            file: r.origin.file, location: r.location,
            detail: { ruleId: r.ruleId, stateVar: r.stateVar },
            kind: 'state',
            // ek -> {depth, chainWrite, chainInter, w} for witnesses
            // reachable through that entry.
            witnessByEntry: new Map(),
            // Fallback pool so interaction.location survives even when no
            // entry can reach the pattern.
            fallback: [],
          };
          acc.set(key, f);
        }

        for (const w of r.witnesses) {
          // Reachability of the interaction point is governed by its
          // anchor: the non-modifier function whose frame the point sits
          // in (inlined modifier code shares the enclosing frame).
          const wReach = (w.anchorKey === descKey(desc))
            ? reachMap
            : (reach.get(w.anchorKey) || new Map());
          for (const [ek, chainInter] of wReach.entries()) {
            // The write's own function must be reachable from the same
            // entry: an interaction in a shared callee cannot witness a
            // write in a function the entry never reaches.
            const chainWrite = reachMap.get(ek);
            if (!chainWrite) continue;
            const cand = { depth: w.depth, chainWrite, chainInter, w };
            const prior = f.witnessByEntry.get(ek);
            if (!prior || prior.depth > cand.depth) f.witnessByEntry.set(ek, cand);
