// State-update findings carry an `interaction` witness: the external
// interaction that, on the same static path, precedes the storage write.
function finalizeState(f) {
  const d = f.detail;
  const message = `公开入口在外部调用或转账之后写入重入敏感状态 ${d.stateVar}，违反 checks-effects-interactions 顺序`;

  // Entries ordered by shortest write chain, then identity — the same
  // ordering the generic finalizer uses for entryPoints/callChain.
  const cands = [...f.witnessByEntry.values()];
  cands.sort((a, b) => {
    if (a.chainWrite.length !== b.chainWrite.length) {
      return a.chainWrite.length - b.chainWrite.length;
    }
    const ea = a.chainWrite[0];
    const eb = b.chainWrite[0];
    if (ea.contract !== eb.contract) return (ea.contract || '') < (eb.contract || '') ? -1 : 1;
    if (ea.kind !== eb.kind) return ea.kind < eb.kind ? -1 : 1;
    return ea.name < eb.name ? -1 : ea.name > eb.name ? 1 : 0;
  });

  const entryPoints = [];
  for (const c of cands) {
    const e = c.chainWrite[0];
    if (!entryPoints.some((x) => x.name === e.name && x.contract === e.contract &&
                                x.kind === e.kind)) {
      entryPoints.push(e);
    }
  }
  const reachable = entryPoints.length > 0;

  // Single witness: fewest function frames; ties follow entry order, then
  // the earliest interaction position.
  let chosen = null;
  if (reachable) {
    const entryIndex = (e) =>
      entryPoints.findIndex((x) => x.name === e.name && x.contract === e.contract &&
                                  x.kind === e.kind);
    const ranked = [...cands].sort((a, b) => {
      if (a.depth !== b.depth) return a.depth - b.depth;
      const ia = entryIndex(a.chainWrite[0]);
      const ib = entryIndex(b.chainWrite[0]);
      if (ia !== ib) return ia - ib;
      if (a.w.file !== b.w.file) {
        return a.w.file < b.w.file ? -1 : 1;
      }
      return a.w.loc.startOffset - b.w.loc.startOffset;
    });
    chosen = ranked[0];
  } else {
    const ranked = [...f.fallback].sort((a, b) => {
      if (a.depth !== b.depth) return a.depth - b.depth;
      if (a.w.file !== b.w.file) {
        return a.w.file < b.w.file ? -1 : 1;
      }
      return a.w.loc.startOffset - b.w.loc.startOffset;
    });
    chosen = ranked[0] || null;
  }

  const interaction = {
    location: chosen ? locOf(chosen.w.file, chosen.w.loc) : null,
    callChain: reachable && chosen ? chosen.chainInter : [],
  };

  return {
    ruleId: f.ruleId,
    severity: f.severity,
    message,
    location: locOf(f.file, f.location),
    reachable,
    evidence: {
      entryPoints: reachable ? entryPoints : [],
      callChain: reachable ? cands[0].chainWrite : [],
      interaction,
    },
  };
}

