// Walk one frame's effective (modifier-inlined) statements.
const walk = (desc, frame, pre) => {
  const recList = (list, carryP) => {
    let carry = carryP;
    for (const { stmt, origin } of list) {
      const r = rec(stmt, origin, carry);
      if (r.term) return { after: null, term: true };
      carry = r.after;
    }
    return { after: carry, term: false };
  };

  const rec = (s, origin, carryP) => {
    switch (s.kind) {
      case 'block':
        return recList((s.statements || []).map((stmt) => ({ stmt, origin })), carryP);
      case 'unchecked':
        return rec(s.body, origin, carryP);

      case 'if': {
        const preC = mergeA(carryP, atomsOf(s.test, origin, frame, carryP));
        const rt = rec(s.consequent, origin, preC);
        if (!s.alternate) {
          const parts = [preC];
          if (!rt.term) parts.push(rt.after);
          return { after: mergeA(...parts), term: false };
        }
        const re = rec(s.alternate, origin, preC);
        const parts = [];
        if (!rt.term) parts.push(rt.after);
        if (!re.term) parts.push(re.after);
        return { after: parts.length ? mergeA(...parts) : null, term: rt.term && re.term };
      }

      case 'while': {
        const preC = mergeA(carryP, atomsOf(s.test, origin, frame, carryP));
        let carry = preC;
        for (let i = 0; i < MAX_LOOP_ITERS; i++) {
          const rb = rec(s.body, origin, carry);
          const next = rb.term ? carry : mergeA(carry, rb.after);
          if (next.length === carry.length) break;
          carry = next;
        }
        return { after: carry, term: false };
      }

      case 'doWhile': {
        let carry = carryP;
        for (let i = 0; i < MAX_LOOP_ITERS; i++) {
          const rb = rec(s.body, origin, carry);
          let next = rb.term ? carry : mergeA(carry, rb.after);
          next = mergeA(next, atomsOf(s.test, origin, frame, carry));
          if (next.length === carry.length) break;
          carry = next;
        }
        return { after: carry, term: false };
      }

      case 'for': {
        let carry = carryP;
        if (s.init) {
          const ri = rec(s.init, origin, carry);
          if (!ri.term) carry = ri.after;
        }
        for (let i = 0; i < MAX_LOOP_ITERS; i++) {
          if (s.test) carry = mergeA(carry, atomsOf(s.test, origin, frame, carry));
          const rb = rec(s.body, origin, carry);
          let next = rb.term ? carry : mergeA(carry, rb.after);
          if (s.update) next = mergeA(next, atomsOf(s.update, origin, frame, carry));
          if (next.length === carry.length) break;
          carry = next;
        }
        return { after: carry, term: false };
      }

      case 'try': {
        const preTry = mergeA(carryP, atomsOf(s.externalCall, origin, frame, carryP));
        const parts = [];
        const rb = rec(s.body, origin, preTry);
        if (!rb.term) parts.push(rb.after);
        for (const clause of s.clauses || []) {
          const rc = rec(clause, origin, preTry);
          if (!rc.term) parts.push(rc.after);
        }
        return { after: parts.length ? mergeA(...parts) : null, term: parts.length === 0 };
      }

      case 'return':
      case 'throw':
        return { after: null, term: true };

      case 'break':
      case 'continue':
        // May-analysis: another iteration can supply prior events.
        return { after: carryP, term: false };

      case 'varDecl':
        return { after: mergeA(carryP, atomsOf(s.initializer, origin, frame, carryP)), term: false };

      case 'emit':
        return { after: mergeA(carryP, atomsOf(s.expr, origin, frame, carryP)), term: false };

      case 'expression': {
