  // Loop handling with a fixed point. Events accumulated on an earlier
  // iteration (including via normal `continue` / body fall-through, or
  // a `break`-free repeated entry) witness later-iteration writes.
  const recLoop = (s, origin, frame, carryP) => {
    const testAtoms = (c) => atomsOf(s.test, origin, frame, c);
    let entering = carryP;
    if (s.kind === 'for' && s.init) {
      const ri = rec(s.init, origin, entering);
      if (ri.fall) entering = ri.fall;
      // init return/break/continue are degenerate; propagate return.
      if (ri.ret) return flow(null, ri.ret, null, null);
    }
    if (s.kind === 'doWhile') {
      // body runs at least once before the test.
    } else if (s.test) {
      entering = mergeA(entering, testAtoms(entering));
    }

    let ret = null;
    let fall = null;    // events on the exit-by-false-test path
    for (let i = 0; i < MAX_LOOP_ITERS; i++) {
      let bodyPre = entering;
      let bodyRes;
      if (s.kind === 'doWhile') {
        bodyRes = rec(s.body, origin, bodyPre);
        // do-while test evaluated after the body for fall/continue.
        const afterBody = mergeA(...[bodyRes.fall, bodyRes.cont].filter(Boolean));
        const tested = mergeA(afterBody, testAtoms(afterBody.length ? afterBody : bodyPre));
        // re-entry set, and the false-exit set
        const reenter = tested;
        bodyRes = {
          fall: tested, // may exit via false test
          ret: bodyRes.ret, brk: bodyRes.brk, cont: null,
        };
        entering = mergeA(entering, reenter);
        fall = tested;
        if (bodyRes.brk) { fall = mergeA(fall, bodyRes.brk); }
        if (bodyRes.ret) ret = mergeA(ret, bodyRes.ret);
        if (stableEnough(reenter, entering) && i > 0) break;
        continue;
      } else {
        bodyRes = rec(s.body, origin, bodyPre);
      }

      if (bodyRes.ret) ret = mergeA(ret, bodyRes.ret);

      // break exits the loop; the break point itself may exit by test.
      let breakOut = bodyRes.brk;

      // normal completion / continue -> evaluate update (for) then test
      const normal = mergeA(...[bodyRes.fall, bodyRes.cont].filter(Boolean));
      let cycled = normal;
      if (s.kind === 'for' && s.update) {
        cycled = mergeA(cycled, atomsOf(s.update, origin, frame, cycled));
      }
      if (s.test) cycled = mergeA(cycled, testAtoms(cycled));

      const nextEntering = mergeA(entering, cycled);
      // Exit path: false test reachable from fall-through events.
      fall = mergeA(
        ...[fall, bodyRes.fall ? (s.kind === 'for' && s.update
                ? mergeA(bodyRes.fall, atomsOf(s.update, origin, frame, bodyRes.fall))
                : bodyRes.fall) : null,
            breakOut].filter(Boolean));
      if (s.test && bodyRes.fall) {
        // already includes test via cycled for the repeating path;
        // false-exit sees the test too, but test atoms are interactions
        // regardless of branch, so merge them in.
        fall = mergeA(fall, testAtoms(bodyRes.fall));
      }
      if (nextEntering.length === entering.length) { entering = nextEntering; break; }
      entering = nextEntering;
    }
    return flow(fall, ret, null, null);
  };

  const stableEnough = (a, b) => a.length === b.length;

  return recList(view.effectiveStatements(desc), pre);
};

