const mergeA = (...lists) => {
  const best = new Map();
  for (const list of lists) {
    for (const a of list) {
      const k = atomKey(a);
      const prior = best.get(k);
      if (!prior || prior.di > a.di) best.set(k, { ...a });
    }
  }
  return [...best.values()];
};

