mkdir -p /tmp/cs8 && cat > /tmp/cs8/r.sol <<'EOF'
pragma solidity ^0.8.0;
contract R {
    uint256 a;
    function retCallee(address to) internal {
        to.call("");
        return;          // normal return: effects handed back
    }
    function viaReturn(address to) public {
        retCallee(to);
        a = 1;           // SHOULD flag
    }
    function revertCallee(address to) internal {
        to.call("");
        revert("x");     // aborts: effects never reach caller continuation
    }
    function viaRevert(address to) public {
        revertCallee(to);
        a = 2;           // should NOT flag
    }
    function alwaysRet(address to) public {
        to.call("");
        return;
        // a = 3; unreachable (would be parse-valid but skip)
    }
    function brk(address to) public {
        while (true) {
            to.call("");
            break;
        }
        a = 4;           // interaction before break witnesses post-loop write
    }
}
EOF
node bin/contract-sentry.js audit /tmp/cs8/r.sol | node -e '
let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);
const st=j.findings.filter(x=>x.ruleId==="STATE_UPDATE_AFTER_CALL");
console.log("state writes:", st.map(f=>f.location.startLine).sort((x,y)=>x-y).join(","));
console.log("expected: 9 (viaReturn) and 29 (brk); NOT 15 (viaRevert)");
});'

