mkdir -p /tmp/cs13 && cat > /tmp/cs13/two.sol <<'EOF'
pragma solidity ^0.8.0;
contract Two {
    uint256 s;
    function g(address to) internal { to.call(""); }
    function h() internal { s = 1; }
    function entry(address to) public {
        g(to);   // interaction in one callee
        h();     // write in a different callee, later on same path
    }
    function swapped(address to) public {
        h();     // write first
        g(to);   // interaction after -> no witness
    }
}
EOF
node bin/contract-sentry.js audit /tmp/cs13/two.sol | node -e '
let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);
const st=j.findings.filter(x=>x.ruleId==="STATE_UPDATE_AFTER_CALL");
console.log("state writes:", st.map(f=>f.location.startLine).join(","));
for(const f of st) console.log("  L"+f.location.startLine,
  "wChain="+f.evidence.callChain.map(c=>c.name).join("->"),
  "iChain="+f.evidence.interaction.callChain.map(c=>c.name).join("->"));
});'

